---刷新cell状态
function ActivityOpenGridSupplyCell:RefreshCellState(data)
    local isSoldOut = StoreUtils.ProductIsSoldOut(data)
    local isLocked, lockedDescr = self:ProductIsLocked(data)
    local isGray = isSoldOut or isLocked
    KTool.SetActive(self.DisableMask, isGray)
    KTool.SetActive(self.FinishGroup, isSoldOut)
end

function ActivityOpenGridSupplyCell:ProductIsLocked(product)
    if not isSet(product, "unlock") then
        return false
    end
    local isLocked = false
    local lockedDescr = ''
    for i = 1, #product.unlock do
        if product.unlock[i].targetType ==  Constants.CommonUnlockType.OpenGridStoreCard then
            isLocked = self.curFloor < tonumber(product.unlock[i].targetNum)
        else
            isLocked = isLocked or not GameUtils.IsUnlockedSingle(product.unlock[i].targetType, product.unlock[i].targetNum, product.unlock[i].targetId)
        end
        if isLocked then
            lockedDescr = GameUtils.GetUnlockDescription(tostring(product.unlock[i].targetType), tostring(product.unlock[i].targetNum))
            break
        end
    end
    return isLocked, lockedDescr
end

---刷新道具
function ActivityOpenGridSupplyCell:RefreshGoods(data)
    if isNull(data) then return end
    self:SetGoodsShow(data)
    CfUtils.FillText(self.TxtDesc1, data.name)
    -- 库存
    if data.tab == StoreConstants.StoreGiftType.Activity then
        CfUtils.FillText(self.TxtDesc2, localize("活动限购:"))
    else
        CfUtils.FillText(self.TxtDesc2, localize("库存:"))
    end

    if checkNumber(data.stock) == -1 then
        KTool.SetActive(self.GroupDesc2, false)
    else
        KTool.SetActive(self.GroupDesc2, true)
        CfUtils.FillText(self.StockTxtNumber, data.currentStock)
    end

    -- 价格
    local isFree = self:ProductIsFree(data)
    KTool.SetActive(self.PriceGroup, not isFree)
    KTool.SetActive(self.FreeGroup, isFree)
    CfUtils.SetUISwitchImage(self.ImgbgState, isFree and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgCode, isFree and 2 or 1)
    if not isFree then
        local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(data.prices[1].currency))
        if data.prices[1].original ~= 0 then
            KTool.SetActive(self.OriPrice, true)
            KTool.SetActive(self.CurPrice, false)
            CfUtils.FillImage(self.OriPriceIcon, currencyVo.photoPath)
            CfUtils.FillText(self.OriPriceTxt, data.prices[1].current)
            CfUtils.FillImage(self.OriPriceMask, currencyVo.photoPath)
            CfUtils.FillText(self.Txtoriginal, data.prices[1].original)
        else
            KTool.SetActive(self.OriPrice, false)
            KTool.SetActive(self.CurPrice, true)
            CfUtils.FillImage(self.CurPriceIcon, currencyVo.photoPath)
            CfUtils.FillText(self.CurPriceTxt, data.prices[1].current)
        end
    end

    local tabType = checkInt(data.iconId)
    KTool.SetActive(self.DiscountGroup, false)
    KTool.SetActive(self.ActivityTabelGroup, false)
    if tabType == TagType.Activity then
        if data.iconTitle then
            CfUtils.FillText(self.ActivityTabelGroupText, data.iconTitle)
        end
        KTool.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.Discount then
        if data.iconTitle then
            CfUtils.FillText(self.DiscountTxtNumber, data.iconTitle)
        end
        KTool.SetActive(self.DiscountGroup, true)
    end
end

function ActivityOpenGridSupplyCell:SetGoodsShow(data)
    for i = 1, 3 do
        local goodItem = self["GoodNode"..i]
        if goodItem then
            if next(data.rewards) and data.rewards[i] then
                KTool.SetActive(goodItem.gameObject,true)
                local _PosAndScale = PosAndScale[#data.rewards]
                local scale = _PosAndScale[i].scale
                local pos = _PosAndScale[i].pos
                goodItem.transform.localPosition = Vector3.New(pos[1],pos[2],0)
                CfUtils.RefeshGoodGo(goodItem,data.rewards[i].goodsId, data.rewards[i].num, scale, nil, function()
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.rewards[i].goodsId)
                    if isTable(goodsVo) then
                        GameUtils.ShowCommonTipsBoard(goodItem.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
                    end
                end)
            else
                KTool.SetActive(goodItem.gameObject,false)
            end
        end
    end
end

--region private
function ActivityOpenGridSupplyCell:ProductIsFree(product)
    return next(checkTable(product.prices)) == nil
end
return ActivityOpenGridSupplyCell